//! The vanilla block and block-state tables for 1.21.11.
//!
//! Generated from PrismarineJS `minecraft-data` `pc/1.21.11/blocks.json`.
//!
//! See `docs/DESIGN_NOTES.md` §9 for why the id space is vanilla's and how the
//! tables are split. The short version: a [`crate::BlockStateId`] **is** a
//! vanilla flattened block-state id, `0..=29670`, and the hot path —
//! "what are this cell's properties" — is one indexed load into
//! [`STATE_PROPS`].
//!
//! Items are deliberately absent. An item never occupies a cell, so it has no
//! business in the structure the world is made of.

use crate::block::{BlockProperties, BlockStateId};

/// `solid`: a full opaque cube, for occlusion and the SoA solid mask.
