/// Unpack a packed property word.
#[inline]
pub const fn unpack(word: u16) -> BlockProperties {
    BlockProperties {
        solid: word & F_SOLID as u16 != 0,
        collision: word & F_COLLISION as u16 != 0,
        redstone: word & F_REDSTONE as u16 != 0,
        light_emission: ((word >> 3) & 0x0F) as u8,
        light_opacity: ((word >> 7) & 0x0F) as u8,
    }
}

/// Properties of a block state.
#[inline]
pub fn props_of_state(id: BlockStateId) -> Option<BlockProperties> {
    STATE_PROPS.get(id.raw() as usize).copied().map(unpack)
}

/// Unpack one block row — the block's own default properties.
pub const fn props_of_row(row: (&str, u8, u8, u8)) -> BlockProperties {
    let (_, flags, emission, opacity) = row;
    BlockProperties {
        solid: flags & F_SOLID != 0,
        collision: flags & F_COLLISION != 0,
        redstone: flags & F_REDSTONE != 0,
        light_emission: emission,
        light_opacity: opacity,
    }
}

/// The block id for a block name (no state properties).
pub fn block_id_of(name: &str) -> Option<u16> {
    BY_NAME
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .map(|i| BY_NAME[i].1)
}

/// The block a state belongs to, as `(id, name)`.
pub fn block_of_state(id: BlockStateId) -> Option<(u16, &'static str)> {
    let b = *STATE_TO_BLOCK.get(id.raw() as usize)?;
    Some((b, BLOCKS[b as usize].0))
}

/// The default state of a block, by name.
///
/// What "place this block" means when nothing has chosen a state yet.
pub fn default_state(name: &str) -> Option<BlockStateId> {
    block_id_of(name).map(|b| BlockStateId(DEFAULT_STATE[b as usize]))
}

/// Every state of a block, by name.
pub fn states_of(name: &str) -> Option<std::ops::RangeInclusive<u32>> {
    let b = block_id_of(name)?;
    let (lo, hi) = STATE_RANGE[b as usize];
    Some(lo..=hi)
}
